-- ETL and data-loading: MERGE, multitable insert, bulk loads, upserts
MERGE INTO customers c USING customers_stage s ON (c.customer_id = s.customer_id) WHEN MATCHED THEN UPDATE SET c.email = s.email, c.updated_at = SYSDATE WHEN NOT MATCHED THEN INSERT (customer_id, first_name, last_name, email) VALUES (s.customer_id, s.first_name, s.last_name, s.email);
MERGE INTO inventory i USING (SELECT product_id, SUM(qty) AS qty FROM shipments GROUP BY product_id) s ON (i.product_id = s.product_id) WHEN MATCHED THEN UPDATE SET i.on_hand = i.on_hand + s.qty;
MERGE INTO inventory i USING (SELECT :pid AS product_id, :qty AS qty FROM dual) s ON (i.product_id = s.product_id) WHEN MATCHED THEN UPDATE SET i.on_hand = s.qty WHEN NOT MATCHED THEN INSERT (product_id, on_hand) VALUES (s.product_id, s.qty);
MERGE INTO employees e USING hr_updates u ON (e.employee_id = u.employee_id) WHEN MATCHED THEN UPDATE SET e.salary = u.salary DELETE WHERE (u.status = 'TERMINATED');
MERGE INTO employees e USING hr_updates u ON (e.employee_id = u.employee_id) WHEN MATCHED THEN UPDATE SET e.salary = u.salary WHERE e.salary <> u.salary WHEN NOT MATCHED THEN INSERT (employee_id, salary) VALUES (u.employee_id, u.salary) WHERE u.status = 'ACTIVE';
MERGE /*+ PARALLEL(t 4) */ INTO target t USING source s ON (t.id = s.id) WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.val);
INSERT ALL INTO sales_east (sale_id, amount) VALUES (sale_id, amount) INTO sales_west (sale_id, amount) VALUES (sale_id, amount) SELECT sale_id, amount FROM sales_stage;
INSERT ALL WHEN region = 'E' THEN INTO sales_east VALUES (sale_id, amount) WHEN region = 'W' THEN INTO sales_west VALUES (sale_id, amount) ELSE INTO sales_other VALUES (sale_id, amount) SELECT sale_id, region, amount FROM sales_stage;
INSERT FIRST WHEN amount > 10000 THEN INTO big_sales VALUES (sale_id, amount) ELSE INTO small_sales VALUES (sale_id, amount) SELECT sale_id, amount FROM sales_stage;
INSERT INTO t1 (a, b) SELECT a, b FROM t2 WHERE NOT EXISTS (SELECT 1 FROM t1 WHERE t1.a = t2.a);
INSERT INTO dest SELECT * FROM src LOG ERRORS INTO err$_dest ('nightly load') REJECT LIMIT UNLIMITED;
INSERT INTO t (id, name) VALUES (1, 'a');
INSERT INTO t (id, created) VALUES (:1, DEFAULT);
INSERT INTO emp_summary (department_id, total) SELECT department_id, SUM(salary) FROM employees GROUP BY department_id;
INSERT INTO log_table VALUES (log_seq.NEXTVAL, SYSDATE, 'started');
UPDATE (SELECT e.salary AS old_sal, n.salary AS new_sal FROM employees e JOIN new_salaries n ON e.employee_id = n.employee_id) SET old_sal = new_sal;
UPDATE employees SET (salary, commission_pct) = (SELECT salary, commission_pct FROM employees WHERE employee_id = 205) WHERE employee_id = 206;
UPDATE orders o SET (o.total_amount, o.item_count) = (SELECT SUM(quantity * unit_price), COUNT(*) FROM order_items i WHERE i.order_id = o.order_id) WHERE o.status = 'NEW';
UPDATE customers SET last_login = SYSTIMESTAMP, login_count = NVL(login_count, 0) + 1 WHERE customer_id = :id;
UPDATE employees SET job_id = DEFAULT WHERE employee_id = 1;
DELETE FROM employees e WHERE e.rowid > (SELECT MIN(e2.rowid) FROM employees e2 WHERE e2.email = e.email);
DELETE FROM (SELECT * FROM employees WHERE department_id = 10) WHERE salary < 1000;
DELETE employees WHERE employee_id = 999;
DELETE FROM orders WHERE order_date < ADD_MONTHS(SYSDATE, -36) RETURNING COUNT(*) INTO :cnt;
CREATE TABLE stage_load AS SELECT * FROM src_table WHERE load_date >= TRUNC(SYSDATE) - 1;
TRUNCATE TABLE stage_load DROP STORAGE;
SELECT COUNT(*) FROM stage_load s WHERE NOT EXISTS (SELECT NULL FROM dest d WHERE d.id = s.id);
SELECT s.id, d.id FROM src s FULL OUTER JOIN dest d ON s.id = d.id WHERE s.id IS NULL OR d.id IS NULL;
SELECT id, COUNT(*) FROM stage_load GROUP BY id HAVING COUNT(*) > 1;
SELECT * FROM stage_load WHERE ORA_HASH(id) = ORA_HASH(:v);
SELECT STANDARD_HASH(payload, 'SHA256') AS h FROM stage_load;
SELECT DBMS_RANDOM.VALUE(1, 100) FROM dual;
SELECT DBMS_LOB.GETLENGTH(notes) FROM customers WHERE notes IS NOT NULL;
SELECT UTL_RAW.CAST_TO_VARCHAR2(HEXTORAW('48656C6C6F')) FROM dual;
SELECT TO_CLOB('abc') || TO_CLOB('def') FROM dual;
SELECT employee_id, TO_CHAR(hire_date, 'IYYY-IW') AS iso_week FROM employees;
SELECT * FROM src_table@etl_link s WHERE s.updated_at > (SELECT NVL(MAX(updated_at), DATE '1970-01-01') FROM dest_table);
SELECT 'A' AS grp, COUNT(*) AS n FROM t1 UNION ALL SELECT 'B', COUNT(*) FROM t2 UNION ALL SELECT 'C', COUNT(*) FROM t3;
